/**
 * @param {number[]} nums
 * @return {number[]}
 */
var minBitwiseArray = function (nums) {
    const res = [];

    for (const num of nums) {
        let cur = -1;

        for (let i = 1; i < num; i++) {
            if ((i | (i + 1)) === num) {
                cur = i;
                break;
            }
        }

        res.push(cur);
    }

    return res;
};
